  private focus(id: string, origin?: EventTarget | null) {
    afterNextRender(() => {
      if (id === 'summary-heading' || (origin && [origin, document.body].includes(document.activeElement))) {
        document.getElementById(id)?.focus();
      }
    }, { injector: this.injector });
  }
}
