import {
  afterNextRender,
  ChangeDetectionStrategy,
  Component,
  inject,
  Injector,
  input,
  OnChanges,
  OnDestroy,
  output,
  signal,
} from '@angular/core';
import { FormControl, FormRecord, ReactiveFormsModule } from '@angular/forms';
import {
  isKindValue,
  validateField,
  type DraftEntry,
  type FieldDefinition,
  type FieldValue,
  type FormDefinition,
} from '@quote/contract';
import type { Subscription } from 'rxjs';
import { QUOTE_CLOCK, QuoteState } from './quote-state';

@Component({
  selector: 'app-details-form',
  imports: [ReactiveFormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './details-form.html',
})
export class DetailsForm implements OnChanges, OnDestroy {
  private readonly store = inject(QuoteState);
  private readonly clock = inject(QUOTE_CLOCK);
  private readonly injector = inject(Injector);
  readonly configuration = input.required<FormDefinition>();
  readonly complete = output<void>();
  protected readonly errors = signal<Record<string, string>>({});
  protected readonly announcement = signal('');
  protected form = new FormRecord<FormControl<FieldValue | null>>({});
  private changes?: Subscription;
  private announcer?: ReturnType<typeof setTimeout>;
  private readonly touched = new Set<string>();
  private readonly badInput = new Set<string>();
  private submitted = false;

  ngOnChanges() {
    this.changes?.unsubscribe();
    this.clearAnnouncement();
    this.errors.set({});
    this.touched.clear();
    this.badInput.clear();
    this.submitted = false;
    const config = this.configuration();
    const draft = this.store.draft(config.country);
    this.form = new FormRecord(
      Object.fromEntries(
        config.fields.map((field) => [
          field.id,
          new FormControl<FieldValue | null>(
            draft[field.id]?.value ?? (field.kind === 'checkbox' ? false : null),
          ),
        ]),
      ),
    );
    this.changes = this.form.valueChanges.subscribe(() => this.save());
  }

  ngOnDestroy() {
    this.changes?.unsubscribe();
    this.clearAnnouncement();
  }

  protected controlId(field: FieldDefinition) {
    return `quote-field-${field.id}`;
  }

  protected helpId(field: FieldDefinition) {
    return `quote-help-${field.id}`;
  }

  protected errorId(field: FieldDefinition) {
    return `quote-error-${field.id}`;
  }

  protected description(field: FieldDefinition) {
    const descriptions = [
      field.helpText && this.helpId(field),
      this.errors()[field.id] && this.errorId(field),
    ].filter(Boolean);
    return descriptions.join(' ') || null;
  }

  protected inputType(field: FieldDefinition) {
    if (field.kind === 'date') return field.kind;
    return field.rules.some((rule) => rule.operator === 'email') ? 'email' : 'text';
  }

  protected onInput(field: FieldDefinition, event: Event) {
    const input = event.target as HTMLInputElement;
    if (input.validity.badInput) this.badInput.add(field.id);
    else this.badInput.delete(field.id);
    if (this.touched.has(field.id) || this.submitted) this.recheck(field, true);
  }

  protected onBlur(field: FieldDefinition) {
    this.touched.add(field.id);
    this.recheck(field, true);
  }

  protected submit(event: Event) {
    event.preventDefault();
    this.submitted = true;
    this.clearAnnouncement();
    const fields = this.configuration().fields;
    const now = this.clock();
    const entries = fields.flatMap((field) => {
      const error = this.fieldError(field, now);
      return error ? [[field.id, error] as const] : [];
    });
    this.errors.set(Object.fromEntries(entries));
    if (entries.length) {
      afterNextRender(() => document.getElementById(`quote-field-${entries[0][0]}`)?.focus(), {
        injector: this.injector,
      });
      return;
    }
    this.save();
    this.complete.emit();
  }

  private save() {
    const config = this.configuration();
    const draft = Object.fromEntries(
      config.fields.map((field) => {
        const raw = this.form.controls[field.id].value;
        const value = raw === '' || !isKindValue(field.kind, raw) ? null : raw;
        return [field.id, { kind: field.kind, value } satisfies DraftEntry];
      }),
    );
    this.store.save(config.country, draft);
  }

  private fieldError(field: FieldDefinition, now: Date) {
    if (this.badInput.has(field.id)) return field.errorMessage;
    return validateField(field, this.form.controls[field.id].value, now)[0];
  }

  private recheck(field: FieldDefinition, announce: boolean) {
    const before = this.errors()[field.id];
    const error = this.fieldError(field, this.clock());
    if (before === error) return;
    this.errors.update((current) => {
      const next = { ...current };
      if (error) next[field.id] = error;
      else delete next[field.id];
      return next;
    });
    if (announce) {
      this.clearAnnouncement();
      if (error)
        this.announcer = setTimeout(() => this.announcement.set(`${field.label}: ${error}`), 250);
    }
  }

  private clearAnnouncement() {
    clearTimeout(this.announcer);
    this.announcement.set('');
  }
}
import { HttpClient } from '@angular/common/http';
import { computed, inject, Injectable, signal } from '@angular/core';
import { decodeTerms, isRecord, type Country, type Terms } from '@quote/contract';
import type { Subscription } from 'rxjs';
import { PlanState } from './plan-state';
import { QuoteState } from './quote-state';

type Outcome = 'approved' | 'rejected';
type Phase = 'idle' | 'loading' | 'ready' | 'unavailable' | 'checking' | 'processing';

type Consent = {
  terms: Terms;
  quote: string;
};

function receiptKey(country: Country) {
  return `quote-receipt-v1:${country}`;
}

function restoreReceipt(country: Country): string | null {
  try {
    const text = sessionStorage.getItem(receiptKey(country));
    if (!text || text.length > 256) return null;
    const input: unknown = JSON.parse(text);
    if (!isRecord(input) || input['version'] !== 1 || input['country'] !== country) return null;
    const number = input['number'];
    return typeof number === 'string' && /^DEMO-[A-F0-9]{24}$/.test(number) ? number : null;
  } catch {
    return null;
  }
}

@Injectable({ providedIn: 'root' })
export class QuotePayment {
  private readonly http = inject(HttpClient);
  private readonly details = inject(QuoteState);
  private readonly plans = inject(PlanState);
  private readonly country = signal<Country | null>(null);
  private readonly currentPhase = signal<Phase>('idle');
  private readonly currentTerms = signal<Terms | null>(null);
  private readonly consent = signal<Consent | null>(null);
  private readonly receipts = signal<Partial<Record<Country, string>>>({});
  private readonly changed = signal(false);
  private readonly rejected = signal(false);
  private generation = 0;
  private request?: Subscription;
  private simulation?: ReturnType<typeof setTimeout>;

  readonly phase = this.currentPhase.asReadonly();
  readonly terms = this.currentTerms.asReadonly();
  readonly termsChanged = this.changed.asReadonly();
  readonly paymentRejected = this.rejected.asReadonly();
  readonly busy = computed(() => this.phase() === 'checking' || this.phase() === 'processing');
  readonly accepted = computed(() => {
    const country = this.country();
    const consent = this.consent();
    const terms = this.terms();
    return (
      !!country &&
      !!consent &&
      !!terms &&
      this.sameTerms(consent.terms, terms) &&
      consent.quote === this.quoteSnapshot(country)
    );
  });
  readonly canPay = computed(() => {
    const country = this.country();
    return !!country && this.phase() === 'ready' && this.accepted() && !this.receipt(country);
  });

  enter(country: Country) {
    this.leave();
    this.country.set(country);
    this.loadTerms(country);
  }

  leave() {
    this.generation++;
    this.request?.unsubscribe();
    clearTimeout(this.simulation);
    this.country.set(null);
    this.currentPhase.set('idle');
    this.currentTerms.set(null);
    this.consent.set(null);
    this.changed.set(false);
    this.rejected.set(false);
  }

  receipt(country: Country) {
    return this.receipts()[country] ?? restoreReceipt(country);
  }

  accept(checked: boolean) {
    const country = this.country();
    const terms = this.terms();
    if (this.phase() !== 'ready' || !country || !terms) return;
    const quote = this.quoteSnapshot(country);
    this.consent.set(checked && quote !== null ? { terms, quote } : null);
    if (checked) this.changed.set(false);
  }

  retryTerms() {
    const country = this.country();
    if (country && this.phase() === 'unavailable') this.loadTerms(country);
  }

  pay(outcome: Outcome) {
    const country = this.country();
    const consent = this.consent();
    if (!country || !consent || !this.canPay() || consent.quote !== this.quoteSnapshot(country))
      return;
    const generation = ++this.generation;
    this.currentPhase.set('checking');
    this.rejected.set(false);
    const stillCurrent = () => this.generation === generation && this.country() === country;
    const stillEligible = () =>
      this.consent() === consent && this.quoteSnapshot(country) === consent.quote;
    this.readTerms(country, generation, (terms) => {
      this.applyTerms(terms);
      if (!this.sameTerms(terms, consent.terms) || !stillEligible()) {
        this.currentPhase.set('ready');
        return;
      }
      this.currentPhase.set('processing');
      this.simulation = setTimeout(() => {
        if (!stillCurrent() || this.phase() !== 'processing') return;
        if (stillEligible()) {
          if (outcome === 'approved') this.complete(country);
          else this.rejected.set(true);
        }
        this.currentPhase.set('ready');
      }, 450);
    });
  }

  private loadTerms(country: Country) {
    this.currentPhase.set('loading');
    this.readTerms(country, ++this.generation, (terms) => {
      this.applyTerms(terms);
      this.currentPhase.set('ready');
    });
  }

  private readTerms(country: Country, generation: number, ready: (terms: Terms) => void) {
    this.request?.unsubscribe();
    const stillCurrent = () => generation === this.generation && this.country() === country;
    const unavailable = () => {
      if (stillCurrent()) this.currentPhase.set('unavailable');
    };
    this.request = this.http
      .get<unknown>(`/api/quote-content/v1/${country}/terms`, { timeout: 10_000 })
      .subscribe({
        next: (input) => {
          if (!stillCurrent()) return;
          const terms = decodeTerms(input, country);
          const previous = this.terms();
          if (
            !terms ||
            (previous && previous.revision === terms.revision && previous.text !== terms.text)
          ) {
            unavailable();
          } else {
            ready(terms);
          }
        },
        error: unavailable,
      });
  }

  private applyTerms(terms: Terms) {
    const previous = this.terms();
    if (previous && !this.sameTerms(previous, terms)) {
      this.consent.set(null);
      this.changed.set(true);
    }
    this.currentTerms.set(terms);
  }

  private sameTerms(first: Terms, second: Terms) {
    return (
      first.country === second.country &&
      first.revision === second.revision &&
      first.text === second.text
    );
  }

  private quoteSnapshot(country: Country) {
    const state = this.details.state();
    const catalog = this.plans.view();
    const selected = this.plans.selected(country);
    if (
      state.phase !== 'ready' ||
      state.country !== country ||
      !this.details.canContinue(country) ||
      catalog.phase !== 'ready' ||
      catalog.country !== country ||
      !catalog.checkedForSummary ||
      !selected
    )
      return null;
    return JSON.stringify([
      this.details.draftRevision(country),
      state.form.fields.map(({ id, kind }) => [id, kind]),
      selected.id,
      selected.basePrice.amountMinor,
      selected.basePrice.currency,
    ]);
  }

  private complete(country: Country) {
    if (this.receipt(country)) return;
    const bytes = crypto.getRandomValues(new Uint8Array(12));
    const number =
      'DEMO-' +
      Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0'))
        .join('')
        .toUpperCase();
    this.receipts.update((receipts) => ({ ...receipts, [country]: number }));
    try {
      sessionStorage.setItem(receiptKey(country), JSON.stringify({ version: 1, country, number }));
    } catch {
      // The completed receipt stays locked and recoverable in memory.
    }
  }
}
# US-03 — Terminal quote and restart proposal

**Status** Human approved on 2026-11-22 ([approval record](../docs/approvals/US-03-terminal-quote-spec-approval.md))

**Basis** [US-03 Draft 2](US-03.md), [ADR-005](../docs/adr/ADR-005-country-terms-and-simulated-payment.md), [approved design](../docs/design/US-03-summary-and-payment.md), and the project owner's follow-up request.

## Changes to approved decisions

| Approved decision | Proposed revision |
| --- | --- |
| AC-US03-07 and ADR-005 restore a terminal receipt on Summary. The other wizard routes currently remain reachable through history or direct navigation. | Make confirmation the only reachable wizard step for an approved quote until the user explicitly starts a new quote. |
| ADR-005 persists only the country and quote number. The approved confirmation shows the reference. | Preserve a frozen, masked review of the completed Details, chosen plan and final price with the receipt. Restore the same review after reload even if Strapi content changes. This requires revising the minimal receipt storage decision. |
| ADR-005 defines a future reset boundary. The approved design has no reset action. | Add one **Iniciar una nueva cotización** action on the confirmation screen and return to the current country's Details after reset. |

## Proposed acceptance criteria and regression coverage

| ID | Behavior | Regression verification |
| --- | --- | --- |
| AC-US03-R01 | After approval, opening the same country's Details or Plans URL or reaching either via Back or Forward redirects to confirmation without exposing editable fields or plan controls. The receipt and protection survive reload. The other country's wizard remains independent. | In CO and CL, approve a quote, exercise direct entry and browser history, and reload. Verify the same reference, no editable controls and country isolation. |
| AC-US03-R02 | Confirmation displays the approval, quote reference and read-only Details and plan/final price as captured at approval. The document remains masked. Changes to live form labels, plan prices or availability do not alter a completed quote. | In both countries, verify the approved projection and masked value, then reload after a changed or unavailable catalog and compare the receipt and projection. |
| AC-US03-R03 | Starting a new quote clears the current country's entered data, selected plan, consent, payment attempt and terminal receipt from memory and wizard persistence. It opens same-country Details with configured defaults. Subsequent reloads and old history entries cannot restore the previous approval. | In both countries, reset after approval, reload and revisit the old Summary URL. Verify the old reference and selection are absent, new Details can be entered, and a subsequent approval has a new reference. |
| AC-US03-R04 | Rejection preserves edit and plan navigation, terms checks, and retry with the entered values and selected plan retained. | In both countries, reject, return to Details and Plans, verify retained values and selection, and retry to approval. |

## Decisions for architecture and design review

- Propose persisting only the frozen display projection needed for the receipt, including the already masked document value. Keep the existing country- and tab-scoped boundary. Do not derive historical values from mutable drafts or live content after approval.
- Existing minimal-format receipts already in open tabs have no historical review projection. Propose restoring those receipts with the same reference, terminal route protection and restart action. Display the full read-only review on newly approved receipts. Do not reconstruct an older completed quote from mutable data.
- Preserve the approved principle of releasing the terminal lock last. Specify reset failure handling so a partial persistence failure does not report a successful restart and allow the old approval to return on reload.
- Extend the existing confirmation design with a read-only review and a keyboard-accessible restart action that moves focus to the same-country Details heading after success.

The specification revision is approved. ADR-005 and the confirmation design require their own revisions and approval before implementation.

